/** The deployment selection a run was given, repeated on every command it suggests. */
export interface CommandSelection {
    deployment?: string | undefined;
    partition?: string | undefined;
    allPartitions?: boolean | undefined;
}
/** What a suggested command needs from the current run. */
export interface FollowUpContext {
    /** `this.config.bin`: the standalone binary, or the host CLI mounting it. */
    bin: string;
    selection?: CommandSelection;
}
/**
 * A complete command line to suggest to the user: the binary that is running,
 * the `workflows` topic when mounted in a host CLI, `words`, then the selection
 * flags of the current run.
 */
export declare function followUpCommand({ bin, selection }: FollowUpContext, ...words: string[]): string;
